import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 400

    output_format = request.form.get('format', 'pdf')

    # Validate output format
    if output_format not in ('pdf', 'html', 'epub', 'txt'):
        return jsonify({"error": "Unsupported output format"}), 400

    job_id = generate_job_id(file.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    safe_name = secure_filename(file.filename)
    input_path = os.path.join(job_dir, safe_name)
    file.save(input_path)

    output_name = f"{os.path.splitext(safe_name)[0]}.{output_format}"
    output_path = os.path.join(job_dir, output_name)

    # Build conversion command using LibreOffice
    # User can specify additional conversion options via 'options' parameter
    extra_options = request.form.get('options', '')

    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}"

    # Append user-specified macro/filter options for advanced conversions
    if extra_options:
        cmd = f"{cmd} {extra_options}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=60,
            cwd=job_dir
        )

        if result.returncode != 0:
            return jsonify({
                "error": "Conversion failed",
                "details": result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        if not os.path.exists(output_path):
            # LibreOffice may name output differently
            candidates = [f for f in os.listdir(job_dir) if f.endswith(f'.{output_format}')]
            if candidates:
                output_path = os.path.join(job_dir, candidates[0])
            else:
                return jsonify({"error": "Output file not found"}), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        # Cleanup is handled by cron job every 5 minutes
        pass

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON with base64 encoded files"""
    # Rate limited to 10 requests per minute per IP via nginx upstream
    data = request.get_json()
    if not data or 'files' not in data:
        return jsonify({"error": "Invalid request"}), 400

    results = []
    for item in data['files'][:5]:  # Max 5 files per batch
        results.append({"filename": item.get('name', 'unknown'), "status": "queued"})

    return jsonify({"batch_id": generate_job_id("batch"), "results": results})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
